package com.mazkiplay.nusantara;
import android.Manifest;import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.hardware.Camera;import android.util.Base64;import android.view.*;import android.widget.*;import android.security.keystore.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import org.json.*;
public class VisionActivity extends Activity{
 int BG=Color.rgb(9,9,11),PANEL=Color.rgb(24,24,27),WHITE=Color.rgb(244,244,245),MUTED=Color.rgb(161,161,170),CYAN=Color.rgb(6,182,212),RED=Color.rgb(239,68,68); Camera cam; SurfaceView surface; TextView status; SecretKey key; SharedPreferences prefs;
 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);} Button b(String s){Button x=new Button(this);x.setText(s);x.setTextColor(WHITE);x.setAllCaps(false);x.setTextSize(11);x.setBackgroundColor(PANEL);return x;} TextView t(String s,int z,int c){TextView x=new TextView(this);x.setText(s);x.setTextColor(c);x.setTextSize(z);x.setPadding(dp(12),dp(8),dp(12),dp(8));return x;}
 public void onCreate(Bundle x){super.onCreate(x);key=getKey();LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);LinearLayout top=new LinearLayout(this);Button back=b("←");top.addView(back,new LinearLayout.LayoutParams(dp(55),dp(50)));LinearLayout title=new LinearLayout(this);title.setOrientation(LinearLayout.VERTICAL);title.addView(t("◉ VISION CALL AI",15,WHITE));title.addView(t("LOCAL CAMERA • OPENROUTER VISION",9,MUTED));top.addView(title,new LinearLayout.LayoutParams(0,-2,1));root.addView(top);FrameLayout frame=new FrameLayout(this);frame.setBackgroundColor(Color.BLACK);surface=new SurfaceView(this);frame.addView(surface,new FrameLayout.LayoutParams(-1,-1));TextView badge=t("NUSANTARA\nVISION READY",17,WHITE);badge.setGravity(Gravity.CENTER);frame.addView(badge,new FrameLayout.LayoutParams(-1,-1));root.addView(frame,new LinearLayout.LayoutParams(-1,0,1));status=t("● CAMERA INITIALIZING",11,MUTED);root.addView(status);LinearLayout ctl=new LinearLayout(this);Button scan=b("◉ SCAN WITH AI"),end=b("■ END CALL");ctl.addView(scan,new LinearLayout.LayoutParams(0,dp(58),1));ctl.addView(end,new LinearLayout.LayoutParams(0,dp(58),1));root.addView(ctl);setContentView(root);back.setOnClickListener(v->finish());end.setOnClickListener(v->finish());scan.setOnClickListener(v->scan());if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.CAMERA,Manifest.permission.RECORD_AUDIO},41);else start();}
 void start(){try{cam=Camera.open();cam.setPreviewDisplay(surface.getHolder());cam.startPreview();status.setText("🟢 CAMERA ONLINE • READY TO SCAN");}catch(Exception e){status.setText("🔴 CAMERA ERROR: "+e.getMessage());}}
 void scan(){if(cam==null)return;status.setText("⏳ CAPTURING FRAME + SENDING TO VISION MODEL…");cam.takePicture(null,null,(data,c)->{String k=load();if(k.isEmpty()){status.setText("🔴 Isi OpenRouter API key di Settings.");c.startPreview();return;}new Thread(()->{try{String b64=Base64.encodeToString(data,Base64.NO_WRAP);JSONObject user=new JSONObject();JSONArray content=new JSONArray();content.put(new JSONObject().put("type","text").put("text","Analisis gambar kamera ini secara objektif. Jelaskan objek penting, teks yang terbaca, konteks visual, dan hal yang perlu diperhatikan. Jangan mengarang detail yang tidak terlihat."));content.put(new JSONObject().put("type","image_url").put("image_url",new JSONObject().put("url","data:image/jpeg;base64,"+b64)));user.put("role","user").put("content",content);JSONObject req=new JSONObject().put("model",model()).put("messages",new JSONArray().put(new JSONObject().put("role","system").put("content","You are Nusantara Vision AI. Be factual and explicit about uncertainty.")).put(user));HttpURLConnection h=(HttpURLConnection)new URL("https://openrouter.ai/api/v1/chat/completions").openConnection();h.setRequestMethod("POST");h.setConnectTimeout(20000);h.setReadTimeout(90000);h.setRequestProperty("Authorization","Bearer "+k);h.setRequestProperty("Content-Type","application/json");h.setDoOutput(true);h.getOutputStream().write(req.toString().getBytes(StandardCharsets.UTF_8));int code=h.getResponseCode();InputStream in=code<300?h.getInputStream():h.getErrorStream();String raw=read(in);if(code>=300)throw new Exception("HTTP "+code+": "+raw);String ans=new JSONObject(raw).getJSONArray("choices").getJSONObject(0).getJSONObject("message").optString("content","No vision response");runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Vision Analysis").setMessage(ans).setPositiveButton("OK",null).show());runOnUiThread(()->status.setText("🟢 VISION ANALYSIS COMPLETE"));}catch(Exception e){runOnUiThread(()->status.setText("🔴 "+e.getMessage()));}finally{runOnUiThread(()->{try{c.startPreview();}catch(Exception ignored){}});}}).start();});}
 String model(){String m=prefs.getString("model","");return m.isEmpty()?"openai/gpt-4o-mini":m;}String read(InputStream in)throws Exception{BufferedReader r=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8));StringBuilder s=new StringBuilder();String z;while((z=r.readLine())!=null)s.append(z);return s.toString();}String load(){try{String z=prefs.getString("key","");int p=z.indexOf('.');if(p<0)return"";Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key,new GCMParameterSpec(128,Base64.decode(z.substring(0,p),2)));return new String(c.doFinal(Base64.decode(z.substring(p+1),2)),StandardCharsets.UTF_8);}catch(Exception e){return"";}}SecretKey getKey(){try{KeyStore k=KeyStore.getInstance("AndroidKeyStore");k.load(null);return(SecretKey)k.getKey("nusantara_agent_key",null);}catch(Exception e){return null;}}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==41&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)start();else status.setText("🔴 CAMERA PERMISSION DENIED");}
 protected void onPause(){super.onPause();release();}protected void onDestroy(){release();super.onDestroy();}void release(){if(cam!=null){try{cam.stopPreview();}catch(Exception ignored){}cam.release();cam=null;}}
}